export type PaginationResult =
  | { ok: true; value: { page: number; pageSize: number; offset: number } }
  | { ok: false; error: string };

export function parsePagination(query: Record<string, string | string[] | undefined>): PaginationResult {
  const allowed = new Set(['page', 'pageSize']);
  for (const key of Object.keys(query)) {
    if (!allowed.has(key)) {
      return { ok: false, error: `Unknown query parameter: ${key}` };
    }
  }

  const parsePositiveSafeInteger = (raw: string | string[] | undefined, name: string, fallback: number, max?: number): { ok: true; value: number } | { ok: false; error: string } => {
    if (raw === undefined) return { ok: true, value: fallback };
    if (Array.isArray(raw)) return { ok: false, error: `${name} must be a string` };
    if (typeof raw !== 'string') return { ok: false, error: `${name} must be a string` };
    if (!/^[1-9][0-9]*$/.test(raw)) return { ok: false, error: `${name} must be a positive integer` };
    const value = Number(raw);
    if (!Number.isSafeInteger(value)) return { ok: false, error: `${name} must be a safe integer` };
    if (value <= 0) return { ok: false, error: `${name} must be greater than zero` };
    if (max !== undefined && value > max) return { ok: false, error: `${name} must be less than or equal to ${max}` };
    return { ok: true, value };
  };

  const page = parsePositiveSafeInteger(query.page, 'page', 1);
  if (!page.ok) return page;
  const pageSize = parsePositiveSafeInteger(query.pageSize, 'pageSize', 20, 100);
  if (!pageSize.ok) return pageSize;
  const offset = (page.value - 1) * pageSize.value;
  if (!Number.isSafeInteger(offset)) return { ok: false, error: 'offset must be a safe integer' };
  return { ok: true, value: { page: page.value, pageSize: pageSize.value, offset } };
}

